<script>(function(){var btn=document.getElementById('profileSaveBtn');if(!btn)return;var inputs=document.querySelectorAll('.crm-profile-page input:not([type=checkbox]),.crm-profile-page select,.crm-profile-page textarea');var checks=document.querySelectorAll('.crm-profile-page input[type=checkbox]');function markDirty(){if(!btn.classList.contains('is-dirty')){btn.classList.add('is-dirty');btn.disabled=false}}inputs.forEach(function(el){el.addEventListener('input',markDirty);el.addEventListener('change',markDirty)});checks.forEach(function(el){el.addEventListener('change',markDirty)});var origSave=btn.onclick;btn.addEventListener('click',function(){if(btn.disabled)return;setTimeout(function(){btn.classList.remove('is-dirty');btn.disabled=true},500)})})();</script>
